import SettingsIcon from '@/components/icons/statistics/SettingIcon';
import UserIcon from '@/components/icons/statistics/UserIcon';
import CalendarIcon from '@/components/icons/statistics/CalendarIcon';
import CarIcon from '@/components/icons/statistics/CarIcon';
import StatisticsCards from '@/components/cards/StatisticsCards';
import { Card } from '@/types/statistics';
import { CarStats } from '@/types/dashboard.types';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';


export default function StatisticsCardsComponent() {

    const [data, setData] = useState<CarStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.dashboard.cars,
                });
                setData(res.data.data);
            } catch {
                setData(null);
            }
        };
        fetchStats();
    }, []);

    const getStat = (key: string) => data?.find((s) => s.key === key);

    const cards: Card[] = [
        { text: 'اجمالي السيارات', icon: <CalendarIcon />, num: getStat('total_vehicles')?.value, percent: getStat('total_amount')?.change_percent ?? 0 },
        { text: 'متاح', icon: <UserIcon />, num: getStat('available')?.value, percent: getStat('available')?.change_percent ?? -1 },
        { text: 'تأجير', icon: <SettingsIcon />, num: getStat('rent')?.value, percent: getStat('rent')?.change_percent ?? 8 },
        { text: 'صيانه', icon: <CarIcon />, num: getStat('maintenance')?.value, percent: getStat('maintenance')?.change_percent ?? 10 },
    ];

    return <StatisticsCards cards={cards} />;
}
